import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import './styles.css';

function Navbar({ role, currentNurse, currentPatient, onLogout }) {
    const navigate = useNavigate();
    const location = useLocation();

    const navLink = (label, path) => {
        const active = location.pathname === path;
        return (
            <button
                onClick={() => navigate(path)}
                className={`navbar__link${active ? ' active' : ''}`}
            >
                {label}
            </button>
        );
    };

    // Links change depending on who is logged in
    const renderLinks = () => {
        if (role === 'admin') return (
            <>
                {navLink('Dashboard', '/admin')}
                {navLink('Rooms',     '/admin/rooms')}
                {navLink('Tasks',     '/admin/tasks')}
            </>
        );
        if (role === 'nurse') return (
            <>
                {navLink('Task Pool', '/nurse/pool')}
                {navLink('Dashboard', '/nurse/dashboard')}
            </>
        );
        if (role === 'patient') return (
            <>
                {navLink('My Requests', '/patient')}
            </>
        );
        return null;
    };

    // Label shown on the right side of navbar
    const renderLabel = () => {
        if (role === 'nurse'   && currentNurse)   return `${currentNurse.name} — ${currentNurse.role}`;
        if (role === 'patient' && currentPatient) return `${currentPatient.name} · Room ${currentPatient.room}`;
        if (role === 'admin')                     return 'Admin';
        return '';
    };

    return (
        <nav className="navbar">
            <div className="navbar__logo" onClick={() => {
                if (role === 'admin')   navigate('/admin');
                if (role === 'nurse')   navigate('/nurse/pool');
                if (role === 'patient') navigate('/patient');
            }}>
                🏥 NurseAssist
            </div>

            <div className="navbar__links">
                {renderLinks()}
            </div>

            <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                <span className="navbar__role">{renderLabel()}</span>
                {onLogout && (
                    <button
                        onClick={onLogout}
                        style={{
                            background: 'rgba(255,255,255,0.15)',
                            color: '#fff', border: '1px solid rgba(255,255,255,0.3)',
                            borderRadius: '6px', padding: '0.3rem 0.75rem',
                            cursor: 'pointer', fontSize: '0.78rem',
                            fontFamily: 'Georgia, serif'
                        }}
                    >
                        Sign Out
                    </button>
                )}
            </div>
        </nav>
    );
}

export default Navbar;
